  (SELECT COUNT(*) FROM documents WHERE "projectId" = (SELECT id FROM projects WHERE name LIKE '%Behna%' LIMIT 1)) as doc_count,
  (SELECT COUNT(*) FROM transcriptions WHERE "projectId" = (SELECT id FROM projects WHERE name LIKE '%Behna%' LIMIT 1)) as trans_count;

